def backfill_track_owners(apps, schema_editor):
    """Заполняет владельца существующих треков."""
    Track = apps.get_model('store', 'Track')

    db_alias = schema_editor.connection.alias

    tracks = (
        Track.objects
        .using(db_alias)
        .select_related('album')
        .all()
    )

    for track in tracks.iterator(chunk_size=1000):
        track.owner_id = track.album.artist_id
        track.save(
            using=db_alias,
            update_fields=('owner',),
        )


